:root{--font-sans:'Inter Tight',Inter,-apple-system,sans-serif;--font-mono:'JetBrains Mono','Fira Code',monospace;--font-serif:'Newsreader',Georgia,serif;--feat:"ss01","cv11","cv06" /* @kind other */}

:root{
/* canvas + surfaces */
--canvas:#F2F0EF;--canvas-dim:#ECEAE7;--surface:#FFFFFF;--surface-warm:#FBFAF9;--container:#EAE8E5;
/* ink + text */
--ink:#1E1E2E;--ink-2:#262836;--code-bg:#1D1B22;--text:#464555;--text-strong:#262836;--muted:#6F6D7A;--faint:#8A8996;
/* on-dark */
--dark-text:#F2F0EF;--dark-muted:rgba(242,240,239,.62);--dark-faint:rgba(242,240,239,.4);--dark-border:rgba(242,240,239,.12);
/* lines */
--border:#DCD9D6;--border-strong:#CBC7C2;--hairline:rgba(70,69,85,.1);
/* brand */
--blue:#0166FF;--blue-deep:#0052CC;--blue-soft:rgba(1,102,255,.08);--blue-tint:#EDF3FF;--blue-lite:#7FB0FF;
/* status */
--green:#188650;--green-bright:#22C55E;--green-tint:#E7F5ED;
--amber:#F59E0B;--amber-deep:#B45309;--amber-tint:#FBF2E2;
--red:#EF4343;--red-deep:#BC3A3A;--red-tint:#FCEAEA;
/* legacy aliases (v1 names kept live) */
--visible:var(--green);--partial:var(--amber);--invisible:var(--red);--paper:var(--canvas)}

:root{
--w-light:340; /* @kind other */
--w-regular:420; /* @kind other */
--w-medium:520; /* @kind other */
--w-semibold:620; /* @kind other */
--w-heading:720; /* @kind other */
--w-display:760; /* @kind other */
--w-black:800; /* @kind other */
--track-tight:-0.032em; /* @kind other */
--track-heading:-0.028em; /* @kind other */
--track-card:-0.018em; /* @kind other */
--track-caps:0.1em; /* @kind other */
--track-caps-wide:0.12em; /* @kind other */
--fs-body:17px;
--lh-body:1.7; /* @kind other */
/* product UI scale */
--fs-page-title:30px;--fs-section:20px;--fs-card-title:16px;--fs-table:13.5px;--fs-label:11px;--fs-meta:10.5px}
/* editorial headline system: lead phrase + muted accent + blue square end-mark */
.section-heading{position:relative;font-family:var(--font-sans);font-size:52px;font-weight:760;letter-spacing:-0.032em;line-height:1.02;font-feature-settings:"ss01","cv11","cv06";text-wrap:balance;color:var(--text-strong)}
.section-heading::after{content:"";display:inline-block;width:.36em;height:.36em;margin-left:.18em;margin-bottom:.04em;vertical-align:baseline;background:var(--blue);border-radius:2px;transform:translateY(.02em)}
.section-heading.sm{font-size:34px;letter-spacing:-0.028em}
.section-heading.no-mark::after{content:none}
.section-heading .accent{color:rgba(70,69,85,.42);font-weight:640;letter-spacing:-0.024em}
.section-heading .accent-blue{color:var(--blue)}
.section-heading.on-dark{color:var(--dark-text)}
.section-heading.on-dark .accent{color:var(--dark-faint)}
.section-copy{color:rgba(70,69,85,.62);font-size:16px;line-height:1.62;letter-spacing:-0.005em}
.section-copy.on-dark{color:var(--dark-muted)}
.card-heading{color:var(--text-strong);font-size:20px;font-weight:720;letter-spacing:-0.018em;line-height:1.12;font-feature-settings:"ss01","cv11"}
.card-copy{color:rgba(70,69,85,.62);font-size:15px;line-height:1.5}
.font-label{font-family:var(--font-sans);font-weight:520;font-size:11px;text-transform:uppercase;letter-spacing:.1em}
.mono-label{font-family:var(--font-mono);font-weight:500;font-size:11px;text-transform:uppercase;letter-spacing:.08em}
.display-serif{font-family:var(--font-serif);font-weight:420;letter-spacing:-0.014em;line-height:1.04;font-optical-sizing:auto}
.num{font-variant-numeric:tabular-nums;font-feature-settings:"ss01","cv11","tnum"}

:root{--s-1:4px;--s-2:8px;--s-3:12px;--s-4:16px;--s-5:24px;--s-6:32px;--s-7:40px;--s-8:56px;--s-9:80px;--s-10:120px;
--content-max:1120px;--section-y:80px;--card-pad:36px;--card-gap:24px}
.content{max-width:var(--content-max);margin:0 auto;padding:0 24px}

:root{
--r-xs:4px;--r-sm:6px;--r-md:10px;--r-lg:14px;--r-xl:16px;--r-pill:999px;
/* premium shadow scale: spatial hierarchy only, never decorative */
--shadow-sm:0 1px 2px 0 rgba(70,69,85,.04);
--shadow-md:0 4px 12px -2px rgba(70,69,85,.06),0 2px 4px -1px rgba(70,69,85,.04);
--shadow-lg:0 12px 32px -4px rgba(70,69,85,.08),0 4px 8px -2px rgba(70,69,85,.04);
--shadow-card:0 1px 3px 0 rgba(70,69,85,.04),0 0 0 1px rgba(213,209,203,.6);
--shadow-card-hover:0 8px 24px -4px rgba(70,69,85,.08),0 0 0 1px rgba(213,209,203,.8);
--shadow-elevated:0 16px 48px -8px rgba(70,69,85,.1),0 4px 12px -2px rgba(70,69,85,.05);
--shadow-float:0 24px 64px -12px rgba(30,30,46,.16),0 6px 16px -4px rgba(30,30,46,.08),0 0 0 1px rgba(213,209,203,.5)}
.shadow-sm{box-shadow:var(--shadow-sm)}.shadow-md{box-shadow:var(--shadow-md)}.shadow-lg{box-shadow:var(--shadow-lg)}
.shadow-card{box-shadow:var(--shadow-card)}.shadow-card-hover{box-shadow:var(--shadow-card-hover)}
.shadow-elevated{box-shadow:var(--shadow-elevated)}.shadow-float{box-shadow:var(--shadow-float)}
.section-divider{height:1px;background:linear-gradient(90deg,transparent 0%,var(--border) 22%,var(--border) 78%,transparent 100%)}

:root{--ease:cubic-bezier(.22,1,.36,1); /* @kind other */
--dur-fast:220ms; /* @kind other */
--dur-lift:280ms; /* @kind other */
--dur-reveal:500ms /* @kind other */}
@keyframes pulse-dot{0%,100%{transform:scale(1)}50%{transform:scale(1.4)}}
.animate-pulse-dot{animation:pulse-dot 2s ease-in-out infinite}
@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
.animate-float{animation:float 4s ease-in-out infinite}
@keyframes shimmer{0%{background-position:-200% 0}100%{background-position:200% 0}}
.animate-shimmer{background:linear-gradient(90deg,rgba(1,102,255,0) 0%,rgba(1,102,255,.06) 50%,rgba(1,102,255,0) 100%);background-size:200% 100%;animation:shimmer 3s ease-in-out infinite}
@keyframes marquee{0%{transform:translateX(0)}100%{transform:translateX(-50%)}}
.animate-marquee{animation:marquee 30s linear infinite}
@keyframes ticker{0%{transform:translateY(0)}100%{transform:translateY(-50%)}}
.animate-ticker{animation:ticker 20s linear infinite}
@keyframes count-up{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
.animate-count-up{animation:count-up .6s var(--ease) forwards}
@keyframes reveal-up{from{opacity:0;transform:translateY(32px)}to{opacity:1;transform:translateY(0)}}
.animate-reveal{animation:reveal-up .5s var(--ease) both}
@keyframes caret-blink{0%,60%{opacity:1}61%,100%{opacity:0}}
.animate-caret{animation:caret-blink 1.1s steps(1) infinite}
@keyframes border-pulse{0%,100%{border-color:rgba(1,102,255,.25);background-color:rgba(1,102,255,.03)}50%{border-color:rgba(1,102,255,.5);background-color:rgba(1,102,255,.07)}}
.animate-border-pulse{animation:border-pulse 2.5s ease-in-out infinite}
/* pill button lift: machined top edge, directional hover shadow, arrow slide */
.btn-lift{position:relative;isolation:isolate;overflow:hidden;transition:transform 280ms var(--ease),box-shadow 280ms var(--ease),background-color 220ms ease,border-color 220ms ease;will-change:transform;box-shadow:0 1px 0 rgba(70,69,85,.04),inset 0 1px 0 rgba(255,255,255,.07)}
.btn-lift::before{content:"";position:absolute;inset:0;border-radius:inherit;background:linear-gradient(180deg,rgba(255,255,255,.06) 0%,rgba(255,255,255,0) 42%);opacity:0;transition:opacity 320ms ease;pointer-events:none;z-index:0}
.btn-lift>*{position:relative;z-index:1}
.btn-lift:hover{transform:translateY(-1px);box-shadow:0 10px 24px -14px rgba(70,69,85,.28),0 2px 4px -2px rgba(70,69,85,.08),inset 0 1px 0 rgba(255,255,255,.12)}
.btn-lift:hover::before{opacity:1}
.btn-lift:active{transform:translateY(0) scale(.985);transition-duration:90ms}
.btn-arrow{display:inline-block;transition:transform 320ms var(--ease)}
.btn-lift:hover .btn-arrow{transform:translateX(3px)}
.link-reveal{position:relative;display:inline-block}
.link-reveal::after{content:'';position:absolute;left:0;bottom:-2px;height:1px;width:100%;background-color:currentColor;transform:scaleX(0);transform-origin:right center;transition:transform 360ms var(--ease)}
.link-reveal:hover::after{transform:scaleX(1);transform-origin:left center}
.img-editorial{transition:transform 1200ms var(--ease),filter 600ms ease}
.img-editorial:hover{transform:scale(1.025)}
@media (prefers-reduced-motion:reduce){.animate-marquee,.animate-ticker,.animate-float,.animate-pulse-dot,.animate-shimmer{animation:none}}

/* atmosphere: burns, washes, textures, grids, grain. architectural, never decorative-loud */
.light-burn-warm{background:radial-gradient(45% 55% at 18% 18%,rgba(245,158,11,.10) 0%,transparent 65%),radial-gradient(35% 40% at 82% 28%,rgba(1,102,255,.06) 0%,transparent 70%);filter:blur(2px)}
.light-burn-cool{background:radial-gradient(50% 50% at 80% 20%,rgba(1,102,255,.09) 0%,transparent 70%),radial-gradient(45% 50% at 15% 80%,rgba(245,158,11,.06) 0%,transparent 70%)}
.diffusion-glow{width:700px;height:500px;border-radius:50%;background:radial-gradient(ellipse,rgba(1,102,255,.06) 0%,transparent 70%);filter:blur(80px)}
.atmos-warm{position:relative;isolation:isolate}
.atmos-warm::before{content:'';position:absolute;inset:-10% -5% auto -5%;height:80%;z-index:-1;background:radial-gradient(55% 45% at 82% 28%,rgba(1,102,255,.035) 0%,transparent 70%);pointer-events:none}
.atmos-cool-dark{position:relative;isolation:isolate}
.atmos-cool-dark::before{content:'';position:absolute;inset:0;z-index:0;background:radial-gradient(70% 60% at 100% 0%,rgba(1,102,255,.10) 0%,transparent 55%),radial-gradient(55% 50% at 0% 100%,rgba(245,158,11,.05) 0%,transparent 60%);pointer-events:none}
.atmos-cool-dark>*{position:relative;z-index:1}
.texture-dots{background-image:radial-gradient(rgba(70,69,85,.08) 1px,transparent 1px);background-size:18px 18px}
.texture-dots-faint{background-image:radial-gradient(rgba(70,69,85,.05) 1px,transparent 1px);background-size:22px 22px}
.bg-grid-fine{background-image:linear-gradient(rgba(70,69,85,.10) 1px,transparent 1px),linear-gradient(90deg,rgba(70,69,85,.10) 1px,transparent 1px);background-size:48px 48px;-webkit-mask-image:radial-gradient(70% 60% at 50% 40%,#000 0%,transparent 80%);mask-image:radial-gradient(70% 60% at 50% 40%,#000 0%,transparent 80%)}
.section-grid{background-image:linear-gradient(rgba(1,102,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(1,102,255,.035) 1px,transparent 1px);background-size:64px 64px}
.site-texture>section{position:relative;isolation:isolate}
.site-texture>section::before{content:'';position:absolute;inset:0;z-index:0;pointer-events:none;background-image:linear-gradient(rgba(70,69,85,.055) 1px,transparent 1px),linear-gradient(90deg,rgba(70,69,85,.055) 1px,transparent 1px);background-size:56px 56px;-webkit-mask-image:radial-gradient(80% 70% at 50% 42%,#000 0%,transparent 76%);mask-image:radial-gradient(80% 70% at 50% 42%,#000 0%,transparent 76%)}
.site-texture>section:nth-of-type(even)::before{background-position:28px 18px;opacity:.72}
.site-texture>section>*{position:relative;z-index:1}
.noise-bg{position:relative}
.noise-bg::before{content:'';position:absolute;inset:0;opacity:.3;background-image:url("data:image/svg+xml;base64,");background-repeat:repeat;background-size:256px 256px;pointer-events:none;z-index:0}
.noise-bg>*{position:relative;z-index:1}
.grain-overlay::after{content:'';position:fixed;top:0;left:0;width:100vw;height:100vh;pointer-events:none;z-index:9999;opacity:.018;background-image:url("data:image/svg+xml;base64,")}
.edge-fade-y{-webkit-mask-image:linear-gradient(180deg,transparent 0%,#000 8%,#000 92%,transparent 100%);mask-image:linear-gradient(180deg,transparent 0%,#000 8%,#000 92%,transparent 100%)}
.edge-fade-x{-webkit-mask-image:linear-gradient(90deg,transparent 0%,#000 6%,#000 94%,transparent 100%);mask-image:linear-gradient(90deg,transparent 0%,#000 6%,#000 94%,transparent 100%)}
.decorative-line{height:1px;background:linear-gradient(90deg,transparent,var(--border),transparent)}

/* Imagery: photographic treatments, ink wash, grain. Two official grades:
   documentary (warm natural) and signal (B&W, one blue element kept via SeenMark). */
:root{
--ph-grain:url("data:image/svg+xml;base64,"); /* @kind other */
--ph-filter-documentary:saturate(1.05) contrast(1.03) sepia(.08) brightness(1.01); /* @kind other */
--ph-filter-signal:grayscale(1) contrast(1.09) brightness(.99); /* @kind other */
--ink-wash:linear-gradient(112deg,rgba(30,30,46,.93) 26%,rgba(30,30,46,.72) 62%,rgba(22,22,31,.6) 100%); /* @kind other */
}
.ph{position:relative;overflow:hidden;isolation:isolate}
.ph>img{display:block;width:100%;height:100%;object-fit:cover}
.ph-documentary>img{filter:var(--ph-filter-documentary)}
.ph-documentary::after{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(160deg,rgba(245,158,11,.07),transparent 55%),radial-gradient(120% 90% at 50% 8%,transparent 62%,rgba(38,40,54,.16) 100%)}
.ph-signal>img{filter:var(--ph-filter-signal)}
.ph-signal::after{content:'';position:absolute;inset:0;pointer-events:none;background:radial-gradient(120% 90% at 50% 10%,transparent 60%,rgba(22,22,31,.22) 100%)}
.ph-grain::before{content:'';position:absolute;inset:0;z-index:2;pointer-events:none;background:var(--ph-grain);background-size:240px 240px;opacity:.16;mix-blend-mode:overlay}
.seen-region{position:absolute;z-index:1;background:rgba(1,102,255,.34);mix-blend-mode:color;pointer-events:none}
.seen-brackets{position:absolute;z-index:3;pointer-events:none}
.ink-photo{position:relative;overflow:hidden;isolation:isolate;background:var(--ink,#1E1E2E)}
.ink-photo>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:grayscale(.4) contrast(1.06) brightness(.92)}
.ink-photo::after{content:'';position:absolute;inset:0;background:var(--ink-wash)}
.ink-photo::before{content:'';position:absolute;inset:0;z-index:2;pointer-events:none;background:var(--ph-grain);background-size:240px 240px;opacity:.14;mix-blend-mode:overlay}
.ink-photo>*:not(img){position:relative;z-index:3}

*{box-sizing:border-box;border-color:var(--border)}
html{scroll-behavior:smooth;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
body{margin:0;background:var(--canvas);color:var(--text);font-family:var(--font-sans);font-size:17px;line-height:1.7;font-feature-settings:"ss01","cv11","cv06"}
h1,h2,h3,h4,p{margin:0}
a{color:var(--blue);text-decoration:none}
a:hover{color:var(--blue-deep)}
button{font-family:inherit}
::selection{background:rgba(1,102,255,.14)}
::-webkit-scrollbar{width:6px;height:6px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:var(--border);border-radius:3px}
::-webkit-scrollbar-thumb:hover{background:var(--faint)}
/* pill button recipes */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;white-space:nowrap;border-radius:999px;font-family:var(--font-sans);font-size:14px;font-weight:520;letter-spacing:-.005em;padding:12px 24px;border:1px solid transparent;cursor:pointer;text-decoration:none}
.btn-ink{background:var(--ink);color:#fff}
.btn-ink:hover{background:#2A2A3E;color:#fff}
.btn-blue{background:var(--blue);color:#fff}
.btn-blue:hover{background:var(--blue-deep);color:#fff}
.btn-outline{background:transparent;border-color:var(--border-strong);color:var(--text-strong)}
.btn-outline:hover{background:rgba(255,255,255,.6);color:var(--text-strong)}
.btn-ghost{background:transparent;color:var(--text)}
.btn-sm{padding:8px 16px;font-size:13px}
button:focus-visible,.btn:focus-visible,a:focus-visible{outline:2px solid var(--blue);outline-offset:2px;border-radius:4px}
input:focus-visible,select:focus-visible{outline:none}

/* print safety: reveal animations must never leave content invisible on paper (omelette-print-safety) */
@media print{*{animation:none!important}[style*="opacity:0"],[style*="opacity: 0"]{opacity:1!important}}

